// Gateway Upsell System
(function () {
    'use strict';

    // Função para processar upsell
    function processUpsell(produtoId, redirectUrl) {
        // Criar formulário para enviar dados
        const form = document.createElement('form');
        form.method = 'POST';
        form.action = '/api/upsell/process';
        form.style.display = 'none';

        // Adicionar token CSRF
        const csrfToken = document.createElement('input');
        csrfToken.type = 'hidden';
        csrfToken.name = '_token';
        csrfToken.value = document.querySelector('meta[name="csrf-token"]')?.getAttribute('content') || '';
        form.appendChild(csrfToken);

        // Adicionar ID do produto
        const produtoInput = document.createElement('input');
        produtoInput.type = 'hidden';
        produtoInput.name = 'produto_id';
        produtoInput.value = produtoId;
        form.appendChild(produtoInput);

        // Adicionar URL de redirecionamento
        const redirectInput = document.createElement('input');
        redirectInput.type = 'hidden';
        redirectInput.name = 'redirect_url';
        redirectInput.value = redirectUrl;
        form.appendChild(redirectInput);

        // Adicionar ao DOM e submeter
        document.body.appendChild(form);
        form.submit();
    }

    // Função para recusar upsell
    function rejectUpsell() {
        const upsellContainer = document.getElementById('upsell-container');
        if (upsellContainer) {
            upsellContainer.style.display = 'none';
        }
    }

    // Aguardar DOM carregar
    document.addEventListener('DOMContentLoaded', function () {
        // Event listener para botão de aceitar
        document.addEventListener('click', function (e) {
            if (e.target && e.target.id === 'preview-accept') {
                const produtoId = e.target.getAttribute('data-produto-id');
                const redirectUrl = e.target.getAttribute('data-redirect-to');

                if (produtoId) {
                    processUpsell(produtoId, redirectUrl);
                } else {
                    console.error('ID do produto não encontrado');
                }
            }
        });

        // Event listener para link de recusar
        document.addEventListener('click', function (e) {
            if (e.target && e.target.id === 'preview-recuse') {
                rejectUpsell();
            }
        });
    });

    // Expor funções globalmente se necessário
    window.GatewayUpsell = {
        processUpsell: processUpsell,
        rejectUpsell: rejectUpsell
    };
})();

